(* [comment removed for export] *)
#[using="Type"] Lemma art_fi_a_fn : forall regs (M rom : word -> option byte) (raw0 : word) (S p : Z),
  getr regs 1 = raw0 -> getr regs 2 = Z_to_bv 64 S -> getr regs 10 = Z_to_bv 64 p ->
  0x10007fff8000 + 8192 <= S -> S < 2 ^ 47 -> 0 <= p < 2 ^ 64 ->
  wrA M (S - 4096) 4096 ->
  msteps ASEGS (mkst regs (0x8074c : word) M rom)
    (mkst (regupd (regupd (regupd (regupd (regupd regs 1 (Z_to_bv 64 0x80780)) 2 (Z_to_bv 64 (S - 2128))) 8 (Z_to_bv 64 S)) 9 (Z_to_bv 64 p)) 18 raw0)
          (0x8c888 : word) (art_fi_mem M S raw0 regs) rom).
Proof.
